-- Daily F&B Spend by Event Category
-- Pre-aggregated data from PredictHQ for fast dashboard queries
-- Source: Event-Trends-Export CSV (90-day window)

DROP TABLE IF EXISTS ops.vegas_daily_spend;

CREATE TABLE ops.vegas_daily_spend (
  id SERIAL PRIMARY KEY,
  impact_date DATE NOT NULL UNIQUE,
  -- Hospitality spend by category (in dollars)
  spend_concerts INTEGER DEFAULT 0,
  spend_conferences INTEGER DEFAULT 0,
  spend_expos INTEGER DEFAULT 0,
  spend_festivals INTEGER DEFAULT 0,
  spend_performing_arts INTEGER DEFAULT 0,
  spend_sports INTEGER DEFAULT 0,
  -- Total for the day
  spend_total INTEGER GENERATED ALWAYS AS (
    spend_concerts + spend_conferences + spend_expos +
    spend_festivals + spend_performing_arts + spend_sports
  ) STORED,
  -- Metadata
  imported_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- Create index for date range queries
CREATE INDEX idx_vegas_daily_spend_date ON ops.vegas_daily_spend(impact_date);

